package com.tracker.service;
import com.tracker.entity.*; import com.tracker.repository.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*;
@Service public class NotificationAutomation {private final NotificationRepository notifications;private final CertificationRepository certs;private final UserRepository users;public NotificationAutomation(NotificationRepository n,CertificationRepository c,UserRepository u){notifications=n;certs=c;users=u;}
 @Scheduled(cron="${app.notifications.cron:0 0 9 * * *}",zone="${app.notifications.timezone:Asia/Kolkata}") @Transactional public void notifyExpirationsAndPending(){LocalDate soon=LocalDate.now().plusDays(30);certs.findAll().stream().filter(c->c.getStatus()==CertStatus.APPROVED&&c.getExpiryDate()!=null&&!c.getExpiryDate().isBefore(LocalDate.now())&&!c.getExpiryDate().isAfter(soon)).forEach(c->create(c.getUser(),"Certificate expiring soon",c.getCertificationName()+" expires on "+c.getExpiryDate(),"certifications.html"));long pending=certs.countByStatus(CertStatus.PENDING);if(pending>0)users.findAll().stream().filter(u->u.getRole()!=Role.STUDENT).forEach(u->create(u,"Certificates awaiting review",pending+" certificate(s) are awaiting review","admin-dashboard.html#certs"));}
 private void create(User u,String title,String message,String link){if(!notifications.existsByUserIdAndTitleAndMessage(u.getId(),title,message)){Notification n=new Notification();n.setUser(u);n.setTitle(title);n.setMessage(message);n.setLink(link);notifications.save(n);}}
}
